"""Static validation for webhook_endpoint.py (task-local check)."""

import ast
import pathlib
import sys

target = pathlib.Path(__file__).parent / "webhook_endpoint.py"
source = target.read_text(encoding="utf-8")
tree = ast.parse(source, filename=str(target))

failures = []

# 1. Syntax parses (guaranteed by ast.parse above).

# 2. Required imports / handler names present.
for name in ("stripe", "Flask", "request", "jsonify", "SignatureVerificationError"):
    if name not in source:
        failures.append(f"missing identifier: {name}")

for name in ("handle_successful_payment", "handle_failed_payment", "stripe_webhook"):
    if name not in source:
        failures.append(f"missing handler: {name}")

# 3. Both required event branches are dispatched.
for event in ("payment_intent.succeeded", "payment_intent.payment_failed"):
    if event not in source:
        failures.append(f"missing event branch: {event}")

# 4. Signature verification is used before processing.
if "construct_event" not in source:
    failures.append("missing signature verification (construct_event)")

# 5. Idempotency guard exists.
for marker in ("_was_processed", "_mark_processed"):
    if marker not in source:
        failures.append(f"missing idempotency marker: {marker}")

# 6. HTTP status codes used.
for code in ("400", "500", "200"):
    if code not in source:
        failures.append(f"missing status code path: {code}")

if failures:
    print("VALIDATION FAILED:")
    for f in failures:
        print(f"  - {f}")
    sys.exit(1)

print("VALIDATION OK: webhook_endpoint.py parses and covers required behaviors.")
